import{_ as n,o as a,c as p,a3 as l}from"./chunks/framework.BLaSdaBb.js";const d=JSON.parse('{"title":"ubuntu-kitty终端配置","description":"","frontmatter":{},"headers":[],"relativePath":"Linux系统/ubuntu-kitty终端配置.md","filePath":"Linux系统/ubuntu-kitty终端配置.md","lastUpdated":1785313865000}'),i={name:"Linux系统/ubuntu-kitty终端配置.md"};function e(c,s,t,o,r,_){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="ubuntu-kitty终端配置" tabindex="-1">ubuntu-kitty终端配置 <a class="header-anchor" href="#ubuntu-kitty终端配置" aria-label="Permalink to &quot;ubuntu-kitty终端配置&quot;">​</a></h1><h2 id="apt安装kitty包" tabindex="-1">apt安装kitty包 <a class="header-anchor" href="#apt安装kitty包" aria-label="Permalink to &quot;apt安装kitty包&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kitty</span></span></code></pre></div><h2 id="安装字体" tabindex="-1">安装字体 <a class="header-anchor" href="#安装字体" aria-label="Permalink to &quot;安装字体&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonts-jetbrains-mono</span></span></code></pre></div><h2 id="配置输入法使用ibus" tabindex="-1">配置输入法使用ibus <a class="header-anchor" href="#配置输入法使用ibus" aria-label="Permalink to &quot;配置输入法使用ibus&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/w/.config/environment.d/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/w/.config/environment.d/glfw.conf</span></span></code></pre></div><p>输入</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLFW_IM_MODULE=ibus</span></span></code></pre></div><h2 id="修改配置" tabindex="-1">修改配置 <a class="header-anchor" href="#修改配置" aria-label="Permalink to &quot;修改配置&quot;">​</a></h2><p><code>code ~/.config/kitty/kitty.conf</code></p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ══════════════════════════════════════════════════════════════</span></span>
<span class="line"><span>#   Kitty Terminal Config —— 美观 + 实用</span></span>
<span class="line"><span>#   放置路径: ~/.config/kitty/kitty.conf</span></span>
<span class="line"><span>#   使用 Catppuccin Mocha 配色（深色、护眼、对比适中）</span></span>
<span class="line"><span># ══════════════════════════════════════════════════════════════</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 字体设置</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 推荐先安装 Nerd Font（自带图标字形，配合 powerline/starship 更好看）:</span></span>
<span class="line"><span>#   sudo apt install fonts-jetbrains-mono</span></span>
<span class="line"><span># 或手动下载 JetBrains Mono Bold 放入 ~/.local/share/fonts</span></span>
<span class="line"><span>font_family      JetBrains Mono Regular</span></span>
<span class="line"><span>bold_font        auto</span></span>
<span class="line"><span>italic_font      auto</span></span>
<span class="line"><span>bold_italic_font auto</span></span>
<span class="line"><span>font_size        8</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 中文/emoji 混排时字距更协调</span></span>
<span class="line"><span>disable_ligatures never</span></span>
<span class="line"><span>adjust_line_height  105%</span></span>
<span class="line"><span>adjust_column_width 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 光标</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>cursor_shape            beam</span></span>
<span class="line"><span>cursor_beam_thickness   1.5</span></span>
<span class="line"><span>cursor_blink_interval    0.5</span></span>
<span class="line"><span>cursor_stop_blinking_after 15.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 窗口 &amp; 布局</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>window_padding_width      10</span></span>
<span class="line"><span>placement_strategy        center</span></span>
<span class="line"><span>hide_window_decorations   no</span></span>
<span class="line"><span>confirm_os_window_close    0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 背景透明 + 毛玻璃质感（KDE/GNOME 支持合成时效果最佳）</span></span>
<span class="line"><span>background_opacity        0.92</span></span>
<span class="line"><span>background_blur           20</span></span>
<span class="line"><span>dynamic_background_opacity yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>initial_window_width   1000</span></span>
<span class="line"><span>initial_window_height  650</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 窗口间隔（多窗格分屏时）</span></span>
<span class="line"><span>window_margin_width    0</span></span>
<span class="line"><span>single_window_margin_width -1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 标签页（Tab Bar）</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>tab_bar_edge            top</span></span>
<span class="line"><span>tab_bar_style           powerline</span></span>
<span class="line"><span>tab_powerline_style     slanted</span></span>
<span class="line"><span>tab_bar_min_tabs        1</span></span>
<span class="line"><span>tab_title_template       &quot;{index}: {title}&quot;</span></span>
<span class="line"><span>active_tab_font_style    bold-italic</span></span>
<span class="line"><span>inactive_tab_font_style  normal</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 滚动 &amp; 历史记录</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>scrollback_lines          10000</span></span>
<span class="line"><span>scrollback_pager_history_size 50</span></span>
<span class="line"><span>wheel_scroll_multiplier    5.0</span></span>
<span class="line"><span>touch_scroll_multiplier    1.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 鼠标 &amp; URL</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>mouse_hide_wait          3.0</span></span>
<span class="line"><span>url_style                curly</span></span>
<span class="line"><span>detect_urls               yes</span></span>
<span class="line"><span>copy_on_select            yes</span></span>
<span class="line"><span>strip_trailing_spaces     smart</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 性能</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>repaint_delay    10</span></span>
<span class="line"><span>input_delay      3</span></span>
<span class="line"><span>sync_to_monitor  yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># Shell 集成（推荐开启，支持跳转上一条命令/命令状态标记）</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>shell_integration enabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 键位绑定（实用向：分屏、标签、字号、剪贴板）</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>map ctrl+shift+enter   new_window</span></span>
<span class="line"><span>map ctrl+shift+t       new_tab</span></span>
<span class="line"><span>map ctrl+shift+q       close_tab</span></span>
<span class="line"><span>map ctrl+shift+w       close_window</span></span>
<span class="line"><span>map ctrl+shift+right   next_tab</span></span>
<span class="line"><span>map ctrl+shift+left    previous_tab</span></span>
<span class="line"><span>map ctrl+shift+1       goto_tab 1</span></span>
<span class="line"><span>map ctrl+shift+2       goto_tab 2</span></span>
<span class="line"><span>map ctrl+shift+3       goto_tab 3</span></span>
<span class="line"><span>map ctrl+shift+4       goto_tab 4</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 窗格分屏（vim 式方向键）</span></span>
<span class="line"><span>map ctrl+shift+d       new_window_with_cwd</span></span>
<span class="line"><span>map ctrl+shift+]       next_window</span></span>
<span class="line"><span>map ctrl+shift+[       previous_window</span></span>
<span class="line"><span>map ctrl+shift+f       move_window_forward</span></span>
<span class="line"><span>map ctrl+shift+b       move_window_backward</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 字号调整</span></span>
<span class="line"><span>map ctrl+shift+equal   change_font_size all +1.0</span></span>
<span class="line"><span>map ctrl+shift+minus   change_font_size all -1.0</span></span>
<span class="line"><span>map ctrl+shift+0       change_font_size all 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 复制粘贴</span></span>
<span class="line"><span>map ctrl+shift+c       copy_to_clipboard</span></span>
<span class="line"><span>map ctrl+shift+v       paste_from_clipboard</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 快速清屏 &amp; 重载配置</span></span>
<span class="line"><span>map ctrl+shift+k       clear_terminal scroll active</span></span>
<span class="line"><span>map ctrl+shift+r       load_config_file</span></span>
<span class="line"><span>map ctrl+shift+equal   increase_font_size</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 搜索历史输出（需要 kitten 支持，自带）</span></span>
<span class="line"><span>map ctrl+shift+h       show_scrollback</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 配色方案：Catppuccin Mocha</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>foreground              #CDD6F4</span></span>
<span class="line"><span>background              #1E1E2E</span></span>
<span class="line"><span>selection_foreground    #1E1E2E</span></span>
<span class="line"><span>selection_background    #F5E0DC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cursor                  #F5E0DC</span></span>
<span class="line"><span>cursor_text_color       #1E1E2E</span></span>
<span class="line"><span></span></span>
<span class="line"><span>url_color               #F5E0DC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>active_border_color     #B4BEFE</span></span>
<span class="line"><span>inactive_border_color   #6C7086</span></span>
<span class="line"><span>bell_border_color       #F9E2AF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>active_tab_background   #B4BEFE</span></span>
<span class="line"><span>active_tab_foreground   #11111B</span></span>
<span class="line"><span>inactive_tab_background #181825</span></span>
<span class="line"><span>inactive_tab_foreground #A6ADC8</span></span>
<span class="line"><span>tab_bar_background      #11111B</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 标准 16 色</span></span>
<span class="line"><span>color0  #45475A</span></span>
<span class="line"><span>color8  #585B70</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color1  #F38BA8</span></span>
<span class="line"><span>color9  #F38BA8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color2  #A6E3A1</span></span>
<span class="line"><span>color10 #A6E3A1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color3  #F9E2AF</span></span>
<span class="line"><span>color11 #F9E2AF</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color4  #89B4FA</span></span>
<span class="line"><span>color12 #89B4FA</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color5  #F5C2E7</span></span>
<span class="line"><span>color13 #F5C2E7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color6  #94E2D5</span></span>
<span class="line"><span>color14 #94E2D5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>color7  #BAC2DE</span></span>
<span class="line"><span>color15 #A6ADC8</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span># 其他实用小项</span></span>
<span class="line"><span># ─────────────────────────────</span></span>
<span class="line"><span>enable_audio_bell        no</span></span>
<span class="line"><span>visual_bell_duration      0.1</span></span>
<span class="line"><span>remember_window_size      yes</span></span>
<span class="line"><span>allow_remote_control      yes</span></span>
<span class="line"><span>update_check_interval     0</span></span></code></pre></div>`,12)])])}const u=n(i,[["render",e]]);export{d as __pageData,u as default};
